pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user, uint256 amount) public {
        vm.assume(user != address(0));
        amount = bound(amount, 1, 1000000 ether);
        vm.deal(user, amount);
        vm.prank(user);
        c.deposit{value: amount}();
        uint256 initialBalance = address(c).balance;
