pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address payable caller, uint256 depositAmount, uint256 extraAmount) public {
        depositAmount = bound(depositAmount, 1, 10_000 ether);
        extraAmount = bound(extraAmount, 0, 1_000 ether);
        vm.deal(caller, depositAmount + extraAmount);
        uint256 balBefore = address(c).balance;
        vm.prank(caller);
        c.deposit{value: depositAmount}();
        uint256 balAfterDeposit = address(c).balance;
        // Fund the contract with extra ether (e.g., from a different source) to ensure it has enough to cover a failed withdrawal
        vm.deal(address(0xdead), extraAmount);
        vm.prank(address(0xdead));
        (bool success,) = address(c).call{value: extraAmount}("");
        require(success, "funding failed");
        uint256 balBeforeWithdraw = address(c).balance;
        // Make the caller a contract that will reject the ether transfer
        Rejector rejector = new Rejector();
        vm.deal(address(rejector), depositAmount);
        vm.prank(address(rejector));
        c.deposit{value: 0}(); // give credit to rejector
        // Now withdraw from rejector — the reference reverts, the mutant does not
        vm.prank(address(rejector));
        c.withdrawAll();
        uint256 balAfterWithdraw = address(c).balance;
        // In the correct version the withdraw reverts and balance stays same;
        // In the mutant the call fails silently but the credit was zeroed and balance decreased.
        // The rule: after a withdrawal that should have reverted (because recipient reverts), 
        // the balance must not have decreased by more than the credit we tried to withdraw.
        // Here the credit was 0 (we deposited 0), so the balance should be unchanged.
        assertTrue(balAfterWithdraw == balBeforeWithdraw, "Balance should not decrease on failed withdrawal");
    }
}

contract Rejector {
    receive() external payable { revert("I reject"); }
}

